css:
.portfoliosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2433;
    background: linear-gradient(160deg, #f4f2ec 0%, #ece7dc 100%);
    border-radius: 18px;
}

.portfoliosim-container * {
    box-sizing: border-box;
}

.portfoliosim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14213d 0%, #1f2d52 55%, #2a3a6b 100%);
    color: #f6f3ea;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 33, 61, 0.32);
    border-bottom: 4px solid #c79a3a;
}

.portfoliosim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.portfoliosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c879;
    background: rgba(199, 154, 58, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.portfoliosim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcd6c7;
}

.portfoliosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3357;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.portfoliosim-period-counter #currentDay,
.portfoliosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14213d;
}

.portfoliosim-round-name {
    background: #e2d9c2;
    color: #14213d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.portfoliosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a4b1e;
    background: #f4e3d3;
    padding: 4px 12px;
    border-radius: 999px;
}

.portfoliosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.portfoliosim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
    border-top: 4px solid #2a3a6b;
}

.portfoliosim-card-margin { border-top-color: #0f6b4f; }
.portfoliosim-card-capacity { border-top-color: #1f4e8c; }
.portfoliosim-card-yield { border-top-color: #b07d12; }
.portfoliosim-card-board { border-top-color: #6a3fa0; }

.portfoliosim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b6a5c;
}

.portfoliosim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14213d;
}

.portfoliosim-card-margin .portfoliosim-value { color: #0f6b4f; }
.portfoliosim-card-capacity .portfoliosim-value { color: #1f4e8c; }
.portfoliosim-card-yield .portfoliosim-value { color: #b07d12; }
.portfoliosim-card-board .portfoliosim-value { color: #6a3fa0; }

.portfoliosim-sublabel {
    font-size: 0.76rem;
    color: #7d7c6d;
    line-height: 1.35;
}

.portfoliosim-margin-strong .portfoliosim-value { color: #0f6b4f; }
.portfoliosim-margin-weak .portfoliosim-value { color: #c0392b; }

.portfoliosim-capacity-over { border-top-color: #c0392b; }
.portfoliosim-capacity-over .portfoliosim-value { color: #c0392b; }

.portfoliosim-resource-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f4e8c;
    color: #eef4fb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 10px;
    font-weight: 700;
    font-size: 0.92rem;
}

.portfoliosim-resource-bar #sectionsDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.portfoliosim-resource-over #sectionsDisplay {
    color: #ffd1c4;
}

.portfoliosim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14213d;
    color: #f1ede1;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.portfoliosim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c879;
}

.portfoliosim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c79a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.05);
}

.portfoliosim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.portfoliosim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14213d;
    margin-bottom: 6px;
}

.portfoliosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34384a;
}

.portfoliosim-briefing-text strong { color: #0f6b4f; }
.portfoliosim-briefing-text em { color: #8a4b1e; font-style: italic; }

.portfoliosim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.portfoliosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14213d;
    border-bottom: 2px solid #ece7dc;
    padding-bottom: 8px;
}

.portfoliosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #232a44;
    margin: 14px 0 6px;
}

.portfoliosim-container select,
.portfoliosim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc3aa;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f3;
    color: #1f2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.portfoliosim-container select:focus,
.portfoliosim-container input[type="number"]:focus {
    outline: none;
    border-color: #c79a3a;
    box-shadow: 0 0 0 3px rgba(199, 154, 58, 0.18);
}

.portfoliosim-container select option {
    background-color: #ffffff;
    color: #1f2433;
}

.portfoliosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3a;
}

.portfoliosim-range-readout,
.portfoliosim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f4e8c;
    margin-top: 4px;
}

.portfoliosim-range-readout span:last-child,
.portfoliosim-alloc-readout span:nth-child(2) {
    color: #0f6b4f;
    font-weight: 800;
}

.portfoliosim-hint {
    font-size: 0.8rem;
    color: #7d7c6d;
    margin-top: 4px;
    line-height: 1.4;
}

.portfoliosim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.portfoliosim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f2e8;
    border: 1px solid #e4dcc8;
    border-radius: 9px;
    padding: 8px 12px;
}

.portfoliosim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #232a44;
}

.portfoliosim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.portfoliosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.portfoliosim-container .btn-primary {
    background: linear-gradient(135deg, #14213d 0%, #2a3a6b 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(20, 33, 61, 0.28);
}

.portfoliosim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.portfoliosim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdc3aa;
    color: #6b6a5c;
}

.portfoliosim-coach {
    background: #14213d;
    color: #eef0f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 33, 61, 0.24);
    border-left: 5px solid #c79a3a;
}

.portfoliosim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c879;
    margin-bottom: 8px;
}

.portfoliosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.portfoliosim-coach-body strong { color: #f0cf86; }
.portfoliosim-coach-body em { color: #f3b98a; font-style: italic; }

.portfoliosim-history,
.portfoliosim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.portfoliosim-history h3,
.portfoliosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14213d;
}

.portfoliosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #232a44;
}

.portfoliosim-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #14213d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d9c2;
}

.portfoliosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece1;
}

.portfoliosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.portfoliosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .portfoliosim-container {
        padding: 14px;
    }
    .portfoliosim-header h1 {
        font-size: 1.7rem;
    }
    .portfoliosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .portfoliosim-value {
        font-size: 2rem;
    }
    .portfoliosim-clock {
        margin-left: 0;
    }
    .portfoliosim-period-counter {
        font-size: 0.88rem;
    }
    .portfoliosim-resource-bar,
    .portfoliosim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .portfoliosim-alloc-row {
        flex-wrap: wrap;
    }
    .portfoliosim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .portfoliosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   v1.1.0 — Completion debrief (formatCompletionMessage). Append-only, namespaced
   .pf-cm-* so it cannot collide with the base engine or the .portfoliosim-* view.
   Meridian navy/purple palette matched to the header + chart series.
   ============================================================================ */
.pf-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1f2433; text-align: left; max-width: 760px; margin: 0 auto; }
.pf-cm-incomplete { text-align: center; color: #55586a; font-size: 1rem; padding: 18px; }
.pf-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; padding: 20px 22px; margin-bottom: 16px;
    background: linear-gradient(135deg, #1f2433 0%, #2c2550 55%, #4a2f7a 100%); color: #f2f0f8; border-radius: 16px;
    border: 1px solid #2a2440; box-shadow: 0 10px 28px rgba(31, 36, 51, 0.32); }
.pf-cm-score { text-align: center; padding-right: 20px; border-right: 1px solid rgba(242,240,248,0.22); }
.pf-cm-score-num { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #c8b3f0; }
.pf-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #b7add0; margin-left: 2px; }
.pf-cm-score-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; margin-top: 8px; color: #b0aac6; }
.pf-cm-verdict { display: flex; flex-direction: column; justify-content: center; flex: 1 1 auto; min-width: 180px; }
.pf-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: #a98fe0; font-weight: 700; }
.pf-cm-verdict-tier { font-size: 1.55rem; font-weight: 800; letter-spacing: -0.3px; color: #ffffff; margin-top: 4px; }
.pf-cm-section { margin: 0 0 16px; }
.pf-cm-section-h { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1.1px; font-weight: 700; color: #5b5a72; margin-bottom: 9px; }
.pf-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.pf-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.82rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.pf-cm-chip .pf-cm-ico { font-weight: 800; }
.pf-cm-ok { background: #e6f0ea; color: #1f6b45; border-color: #b9dcc6; }
.pf-cm-no { background: #f2e6ee; color: #7d2f5f; border-color: #ddbcd2; }
.pf-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.pf-cm-kpi { background: #f6f5fb; border: 1px solid #e0dced; border-radius: 12px; padding: 12px 14px; text-align: center; }
.pf-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #3a2f66; line-height: 1.1; }
.pf-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #2a2440; margin-top: 4px; }
.pf-cm-kpi-sub { font-size: 0.68rem; color: #6b6a7c; margin-top: 3px; }
.pf-cm-insights { margin: 0; padding-left: 20px; }
.pf-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #2f2b3f; margin-bottom: 7px; }
@media (max-width: 520px) { .pf-cm-score { border-right: none; border-bottom: 1px solid rgba(242,240,248,0.22); padding-right: 0; padding-bottom: 14px; } .pf-cm-head { flex-direction: column; } }

