(function() {
    'use strict';

    class PortfolioAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Portfolio Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.SECTION_CAP = 45;          // free sections for new launches (binding constraint)
            this.BUDGET_CAP = 1200;         // USD 1,200,000 marketing budget, in thousands
            this.SECTIONS_DEMANDED = 78;    // all three at full scale

            // Concept truths.
            this.TRUE_METRIC = `permsection`;   // contribution-margin-per-section
            this.TRUE_RANK = `B`;               // Health Admin ranks #1 on margin per scarce section
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: 20,
                    capacity: 25,
                    yield: 15,
                    board: 10,
                    sectionsUsed: 0,
                    budgetUsed: 0,
                    flagshipRaid: false,
                    subScale: false,
                    marginHistory: [20],
                    capacityHistory: [25],
                    yieldHistory: [15],
                    boardHistory: [10],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    metric: `totalmargin`,
                    rank: `A`,
                    rigor: 50,
                    plan: `allthree`,
                    adjunct: 40,
                    overflow: `none`,
                    spendB: 400,
                    spendA: 400,
                    spendC: 400,
                    price: `hold`,
                    pitch: `revenue`,
                    cut: `vague`,
                    downside: `monitor`,
                    evidence: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const m = document.getElementById(`metricInput`);
                const rk = document.getElementById(`rankInput`);
                const rg = document.getElementById(`rigorInput`);
                if (m) decisions.metric = m.value;
                if (rk) decisions.rank = rk.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const pl = document.getElementById(`planInput`);
                const aj = document.getElementById(`adjunctInput`);
                const ov = document.getElementById(`overflowInput`);
                if (pl) decisions.plan = pl.value;
                if (aj) decisions.adjunct = parseInt(aj.value, 10);
                if (ov) decisions.overflow = ov.value;
                if (!Number.isFinite(decisions.adjunct) || decisions.adjunct < 0 || decisions.adjunct > 100) {
                    warn(`warn_adjunct_range`); return false;
                }
            } else if (round === 3) {
                const sb = document.getElementById(`spendBInput`);
                const sa = document.getElementById(`spendAInput`);
                const sc = document.getElementById(`spendCInput`);
                const pr = document.getElementById(`priceInput`);
                if (sb) decisions.spendB = parseFloat(sb.value);
                if (sa) decisions.spendA = parseFloat(sa.value);
                if (sc) decisions.spendC = parseFloat(sc.value);
                if (pr) decisions.price = pr.value;
                const parts = [decisions.spendB, decisions.spendA, decisions.spendC];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_spend_negative`); return false;
                }
                const total = Math.round(decisions.spendB + decisions.spendA + decisions.spendC);
                if (total !== this.BUDGET_CAP) {
                    warn(`warn_spend_total`); return false;
                }
            } else if (round === 4) {
                const pt = document.getElementById(`pitchInput`);
                const ct = document.getElementById(`cutInput`);
                const dn = document.getElementById(`downsideInput`);
                const ev = document.getElementById(`evidenceInput`);
                if (pt) decisions.pitch = pt.value;
                if (ct) decisions.cut = ct.value;
                if (dn) decisions.downside = dn.value;
                if (ev) decisions.evidence = parseInt(ev.value, 10);
                if (!Number.isFinite(decisions.evidence) || decisions.evidence < 0 || decisions.evidence > 100) {
                    warn(`warn_evidence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let marginDelta = 0, capacityDelta = 0, yieldDelta = 0, boardDelta = 0;
            let sections = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose on contribution-margin-per-section, not sticker price (Common Error 1).
                switch (d.metric) {
                    case `permsection`: marginDelta += 16; boardDelta += 6; coachKey = `coach_r1_persection`; break;
                    case `totalmargin`: marginDelta += 4; boardDelta += 1; coachKey = `coach_r1_totalmargin`; break;
                    case `sticker`: marginDelta -= 10; boardDelta -= 4; coachKey = `coach_r1_sticker`; break;
                    case `demand`: marginDelta -= 8; boardDelta -= 4; coachKey = `coach_r1_demand`; break;
                }

                // Ranking #1 by margin per scarce section: Program B (adjunct-eligible, 90 seats).
                if (d.rank === this.TRUE_RANK) {
                    marginDelta += 12; boardDelta += 4;
                    if (d.metric === this.TRUE_METRIC) coachKey = `coach_r1_diag_sharp`;
                } else if (d.rank === `C`) {
                    marginDelta -= 8; coachKey = `coach_r1_rankc`;
                } else {
                    marginDelta -= 4; coachKey = (coachKey === `coach_r1_persection`) ? `coach_r1_ranka` : coachKey;
                }

                // Diagnostic rigor: did they actually run the funnel + cost math?
                if (d.rigor >= 60) { marginDelta += 6; boardDelta += 4; }
                else if (d.rigor <= 25) { marginDelta -= 6; boardDelta -= 4; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.metric === this.TRUE_METRIC && d.rank === this.TRUE_RANK) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Prioritize under the 45-section ceiling (Common Errors 2 & 5).
                // Base section counts (full-time staffing): B=30, A=22, C=26.
                // Adjunct share trims the eligible-section quality cost but is capped by curriculum.
                switch (d.plan) {
                    case `twostrong`:
                        // Launch B + A full scale, phase C. ~40 base sections -> clean, fits ceiling.
                        sections = 40;
                        marginDelta += 14; capacityDelta += 26; boardDelta += 4;
                        coachKey = `coach_r2_twostrong`;
                        break;
                    case `premiumpair`:
                        // Launch A + C, phase B (drops the BEST margin-per-section program). 48 base sections.
                        sections = 48;
                        marginDelta -= 6; capacityDelta -= 2; boardDelta -= 2;
                        coachKey = `coach_r2_premiumpair`;
                        break;
                    case `allthree`:
                        // All three at reduced scale to fit ~44 sections, but none reaches viable cohort size.
                        sections = 44;
                        marginDelta -= 10; capacityDelta += 4; yieldDelta -= 8;
                        ds.subScale = true;
                        coachKey = `coach_r2_allthree`;
                        break;
                    case `overcommit`:
                        // All three full scale = 78 sections, 33 over the ceiling.
                        sections = 78;
                        marginDelta -= 6; capacityDelta -= 20; boardDelta -= 8;
                        coachKey = `coach_r2_overcommit`;
                        break;
                }

                // Adjunct vs senior-faculty mix: moderate-high adjunct share lowers section cost and
                // lifts contribution margin where the curriculum allows; pushing it to the extreme
                // erodes quality on programs that need senior faculty.
                if (d.adjunct >= 35 && d.adjunct <= 70) {
                    marginDelta += 8; capacityDelta += 4;
                } else if (d.adjunct > 70) {
                    marginDelta += 2; boardDelta -= 4; coachKey = (coachKey === `coach_r2_twostrong`) ? `coach_r2_adjunctheavy` : coachKey;
                } else {
                    // Too little adjunct use: all-senior-faculty staffing burns margin and capacity.
                    marginDelta -= 4; coachKey = (coachKey === `coach_r2_twostrong`) ? `coach_r2_allsenior` : coachKey;
                }

                // Overflow handling — the phantom-capacity test.
                if (sections > this.SECTION_CAP) {
                    switch (d.overflow) {
                        case `none`:
                            // Claiming you fit while the ledger says otherwise = not honest with the constraint.
                            capacityDelta -= 10; boardDelta -= 6; coachKey = `coach_r2_phantom`;
                            break;
                        case `adjunctbuy`:
                            // Disclosed adjunct overload — honest but costly, and quality dips.
                            spend += 0; marginDelta -= 4; capacityDelta -= 4; boardDelta += 2;
                            coachKey = (coachKey === `coach_r2_overcommit` || coachKey === `coach_r2_premiumpair`) ? `coach_r2_adjunctbuy` : coachKey;
                            break;
                        case `raidmba`:
                            // Pull from the flagship MBA — the hidden NPS/rankings bill.
                            capacityDelta -= 16; boardDelta -= 10;
                            ds.flagshipRaid = true;
                            coachKey = `coach_r2_raid`;
                            break;
                    }
                } else if (d.overflow === `raidmba`) {
                    // Raiding when you didn't even need to is gratuitously destructive.
                    capacityDelta -= 8; boardDelta -= 4; ds.flagshipRaid = true; coachKey = `coach_r2_raid`;
                }

                summaryKey = (d.plan === `twostrong` && sections <= this.SECTION_CAP) ? `sum_r2_good` : (d.plan === `overcommit` || ds.flagshipRaid ? `sum_r2_overcommit` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the $1.2M and set tuition (Common Errors 3 & 4).
                const sB = d.spendB, sA = d.spendA, sC = d.spendC;
                spend = sB + sA + sC;

                // Yield-driven allocation: B (90 seats, ~430 apps) needs the most, then A (60, ~285),
                // then the small boutique C (30, ~140). The right shape is sB > sA > sC.
                const yieldWeighted = (sB > sA && sA >= sC && sB >= 450);
                const equalSplit = (Math.abs(sB - sA) <= 50 && Math.abs(sA - sC) <= 50 && Math.abs(sB - sC) <= 50);
                const overfundSmall = (sC >= sB);
                if (yieldWeighted) {
                    yieldDelta += 24; marginDelta += 6; capacityDelta += 6; boardDelta += 4; coachKey = `coach_r3_yieldweighted`;
                } else if (overfundSmall) {
                    yieldDelta -= 10; coachKey = `coach_r3_overfundsmall`;
                } else if (equalSplit) {
                    yieldDelta -= 6; coachKey = `coach_r3_equalsplit`;
                } else {
                    yieldDelta += 4;
                }

                // Pricing under price–yield elasticity.
                switch (d.price) {
                    case `hold`:
                        yieldDelta += 14; marginDelta += 6; boardDelta += 4; coachKey = (yieldWeighted ? `coach_r3_holdsharp` : coachKey); break;
                    case `trim`:
                        // Targeted scholarship lifts yield on the volume program at a small margin cost.
                        yieldDelta += 16; marginDelta -= 2; break;
                    case `premium`:
                        // Holding the 38% yield constant while pushing price +15% = fictional revenue.
                        marginDelta += 4; yieldDelta -= 14; boardDelta -= 6; coachKey = `coach_r3_premium`; break;
                    case `discount`:
                        // Deep discount fills seats but erodes margin and capacity returns.
                        yieldDelta += 6; marginDelta -= 12; coachKey = `coach_r3_discount`; break;
                }

                summaryKey = (yieldWeighted && (d.price === `hold` || d.price === `trim`)) ? `sum_r3_good` : (d.price === `premium` ? `sum_r3_premium` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the portfolio to the Board (Common Error 6 — ignoring the downside).
                switch (d.pitch) {
                    case `integrated`: boardDelta += 14; marginDelta += 2; coachKey = `coach_r4_integrated`; break;
                    case `revenue`: boardDelta -= 2; coachKey = `coach_r4_revenue`; break;
                    case `prestige`: boardDelta -= 6; coachKey = `coach_r4_prestige`; break;
                }

                switch (d.cut) {
                    case `named`: boardDelta += 12; capacityDelta += 2; break;
                    case `vague`: boardDelta -= 2; coachKey = (coachKey === `coach_r4_integrated`) ? `coach_r4_vaguecut` : coachKey; break;
                    case `none`: boardDelta -= 10; coachKey = `coach_r4_nocut`; break;
                }

                switch (d.downside) {
                    case `contingency`: boardDelta += 14; coachKey = (d.pitch === `integrated` && d.cut === `named`) ? `coach_r4_boardready` : coachKey; break;
                    case `monitor`: boardDelta -= 4; coachKey = `coach_r4_monitor`; break;
                    case `ignore`: boardDelta -= 14; coachKey = `coach_r4_ignore`; break;
                }

                // Evidence discipline nudges board readiness and margin credibility.
                boardDelta += Math.round((d.evidence - 60) / 8);
                if (d.evidence >= 70) marginDelta += 2;

                summaryKey = (d.pitch === `integrated` && d.cut === `named` && d.downside === `contingency`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            if (round === 2) ds.sectionsUsed = sections;
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));

            // KPIs move on their deltas, clamped 0–100.
            ds.margin = Math.max(0, Math.min(100, ds.margin + marginDelta));
            ds.capacity = Math.max(0, Math.min(100, ds.capacity + capacityDelta));
            ds.yield = Math.max(0, Math.min(100, ds.yield + yieldDelta));
            ds.board = Math.max(0, Math.min(100, ds.board + boardDelta));

            ds.marginHistory.push(Math.round(ds.margin));
            ds.capacityHistory.push(Math.round(ds.capacity));
            ds.yieldHistory.push(Math.round(ds.yield));
            ds.boardHistory.push(Math.round(ds.board));

            // v1.1.0 fix — persist the composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level
            // score; express_extractHistory -> per-period domainState.performance.overallScore).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                score: composite,
                overallScore: composite,
                margin: Math.round(ds.margin),
                marginDelta: Math.round(marginDelta),
                capacity: Math.round(ds.capacity),
                capacityDelta: Math.round(capacityDelta),
                yield: Math.round(ds.yield),
                yieldDelta: Math.round(yieldDelta),
                board: Math.round(ds.board),
                boardDelta: Math.round(boardDelta),
                sectionsUsed: ds.sectionsUsed,
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

