        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const margin = Math.round(ds.margin);
            const capacity = Math.round(ds.capacity);
            const yld = Math.round(ds.yield);
            const board = Math.round(ds.board);
            return Math.round(margin * 0.30 + capacity * 0.25 + yld * 0.25 + board * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin);
            const capacity = Math.round(ds.capacity);
            const yld = Math.round(ds.yield);
            const board = Math.round(ds.board);

            const composite = this._composite(ds);
            const withinCeiling = ds.sectionsUsed <= this.SECTION_CAP && !ds.flagshipRaid;

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_stalled`;
            if (composite >= 70 && withinCeiling) tierKey = `grade_architect`;
            else if (composite >= 56) tierKey = `grade_disciplined`;
            else if (composite >= 44) tierKey = `grade_defensible`;
            else if (composite >= 32) tierKey = `grade_ontable`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (composite >= 70 && withinCeiling) insights.push(window.mySimulation.t(`insight_architect`));
            else if (composite >= 56) insights.push(window.mySimulation.t(`insight_disciplined`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.flagshipRaid) insights.push(window.mySimulation.t(`insight_raid`));
            if (ds.subScale) insights.push(window.mySimulation.t(`insight_subscale`));
            if (yld < 40) insights.push(window.mySimulation.t(`insight_lowyield`));
            if (margin < 40) insights.push(window.mySimulation.t(`insight_lowmargin`));
            if (board < 40) insights.push(window.mySimulation.t(`insight_lowboard`));
            if (composite >= 70 && withinCeiling && board >= 60) insights.push(window.mySimulation.t(`insight_boardready`));

            return {
                margin: margin,
                capacity: capacity,
                yield: yld,
                board: board,
                composite: composite,
                withinCeiling: withinCeiling,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="pf-cm"><p class="pf-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="pf-cm-chip ` + (ok ? `pf-cm-ok` : `pf-cm-no`) + `">` +
                `<span class="pf-cm-ico">` + (ok ? `\u2713` : `\u2715`) + `</span>` + label + ` \u00b7 ` +
