            const kpi = (label, val, sub) => `<div class="pf-cm-kpi"><div class="pf-cm-kpi-val">` + val +
                `</div><div class="pf-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="pf-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const mOk = s.margin >= 60, cOk = s.capacity >= 60, yOk = s.yield >= 55, bOk = s.board >= 60, ceilOk = !!s.withinCeiling;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="pf-cm">` +
  `<div class="pf-cm-head">` +
    `<div class="pf-cm-score"><div class="pf-cm-score-num">` + Math.round(s.composite) +
       `<span class="pf-cm-score-den">/100</span></div>` +
