  `<div class="pf-cm-section"><div class="pf-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="pf-cm-kpis">` +
      kpi(t(`margin_label`), Math.round(s.margin), t(`margin_sub`)) +
